import AppKit
import Carbon.HIToolbox

// MARK: - Exclusions

enum ExclusionEngine {
    /// Types that password managers and other apps use to mark data that must not be saved.
    static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "com.typeit4me.clipping",
        "net.antelle.keeweb",
    ]

    static func shouldIgnore(types: Set<String>, bundleID: String?, ignoredApps: [String]) -> Bool {
        if !types.isDisjoint(with: concealedTypes) { return true }
        if let b = bundleID, ignoredApps.contains(b) { return true }
        return false
    }
}

// MARK: - Self-write registry

/// Shared between PasteService and ClipboardMonitor. PasteService registers the changeCount
/// it is about to produce; the monitor consumes it and skips the change.
final class SelfWriteRegistry {
    static let shared = SelfWriteRegistry()
    private var expected: [String: Date] = [:]
    private let ttl: TimeInterval = 10

    private func key(_ count: Int, _ pasteboard: NSPasteboard.Name) -> String { "\(pasteboard.rawValue)#\(count)" }

    func register(_ count: Int, pasteboard: NSPasteboard.Name) {
        prune()
        expected[key(count, pasteboard)] = Date()
    }

    func consume(_ count: Int, pasteboard: NSPasteboard.Name) -> Bool {
        prune()
        return expected.removeValue(forKey: key(count, pasteboard)) != nil
    }

    private func prune() {
        let cutoff = Date().addingTimeInterval(-ttl)
        expected = expected.filter { $0.value > cutoff }
    }
}

// MARK: - Clipboard monitor

final class ClipboardMonitor {
    let pasteboard: NSPasteboard
    private var timer: Timer?
    private(set) var lastChangeCount: Int
    var onCapture: ((RawClip, _ bundleID: String?, _ appName: String?) -> Void)?
    var isPaused: () -> Bool = { Preferences.shared.isPaused }
    var ignoredApps: () -> [String] = { Preferences.shared.activeIgnoredApps }

    init(pasteboard: NSPasteboard = .general) {
        self.pasteboard = pasteboard
        lastChangeCount = pasteboard.changeCount
    }

    /// macOS has no public clipboard-changed notification and keeps only the latest contents, so the
    /// change counter is checked on a timer: every 0.15 s normally, and every 0.05 s for 2 s after a
    /// change (copies tend to come in bursts). Reading the counter is a cheap call, and the faster rate
    /// only runs right after real activity, so idle cost is unchanged. A copy that is replaced before
    /// the next check is never visible to any app — that limit can't be removed, only narrowed.
    static let idleInterval: TimeInterval = 0.15
    static let burstInterval: TimeInterval = 0.05
    static let burstDuration: TimeInterval = 2
    private var interval: TimeInterval = ClipboardMonitor.idleInterval
    private var burstUntil = Date.distantPast
    /// Current check interval (for the self-test).
    var currentInterval: TimeInterval { interval }
    /// Ends a burst early (for the self-test).
    func endBurstForTesting() { burstUntil = .distantPast }

    func start(interval: TimeInterval = ClipboardMonitor.idleInterval) {
        stop()
        lastChangeCount = pasteboard.changeCount
        schedule(interval)
    }

    private func schedule(_ newInterval: TimeInterval) {
        timer?.invalidate()
        interval = newInterval
        let t = Timer(timeInterval: newInterval, repeats: true) { [weak self] _ in self?.tick() }
        t.tolerance = newInterval * 0.2
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    func tick() {
        let current = pasteboard.changeCount
        guard current != lastChangeCount else {
            if interval < Self.idleInterval, Date() > burstUntil, timer != nil { schedule(Self.idleInterval) }   // burst over
            return
        }
        lastChangeCount = current
        burstUntil = Date().addingTimeInterval(Self.burstDuration)
        if interval != Self.burstInterval, timer != nil { schedule(Self.burstInterval) }

        // 1. Our own write? (primary guard)
        if SelfWriteRegistry.shared.consume(current, pasteboard: pasteboard.name) { return }

        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        // 2. Marker type (fallback guard)
        if types.contains(NSPasteboard.PasteboardType.pastlyInternal.rawValue) { return }
        if types.isEmpty || isPaused() { return }
        if Preferences.shared.skipNextCopy {          // "Ignore Next Copy"
            Preferences.shared.skipNextCopy = false
            return
        }

        let app = NSWorkspace.shared.frontmostApplication
        if ExclusionEngine.shouldIgnore(types: types, bundleID: app?.bundleIdentifier, ignoredApps: ignoredApps()) { return }

        let raw = RawClip.read(from: pasteboard, types: types)
        onCapture?(raw, app?.bundleIdentifier, app?.localizedName)
    }
}

// MARK: - Text transforms

enum TextTransform: String, CaseIterable, Identifiable {
    case uppercase, lowercase, titleCase, trimmed, singleLine, urlEncoded, urlDecoded, jsonPretty

    var id: String { rawValue }

    var title: String {
        switch self {
        case .uppercase: return "UPPERCASE"
        case .lowercase: return "lowercase"
        case .titleCase: return "Title Case"
        case .trimmed: return "Trim Whitespace"
        case .singleLine: return "Join Into One Line"
        case .urlEncoded: return "URL-Encode"
        case .urlDecoded: return "URL-Decode"
        case .jsonPretty: return "Pretty-Print JSON"
        }
    }

    func apply(_ s: String) -> String {
        switch self {
        case .uppercase: return s.uppercased()
        case .lowercase: return s.lowercased()
        case .titleCase: return s.capitalized
        case .trimmed: return s.trimmingCharacters(in: .whitespacesAndNewlines)
        case .singleLine:
            return s.components(separatedBy: .newlines)
                .map { $0.trimmingCharacters(in: .whitespaces) }
                .filter { !$0.isEmpty }
                .joined(separator: " ")
        case .urlEncoded:
            var allowed = CharacterSet.alphanumerics
            allowed.insert(charactersIn: "-._~")
            return s.addingPercentEncoding(withAllowedCharacters: allowed) ?? s
        case .urlDecoded:
            return s.removingPercentEncoding ?? s
        case .jsonPretty:
            guard let data = s.data(using: .utf8),
                  let obj = try? JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed]),
                  let out = try? JSONSerialization.data(withJSONObject: obj, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes, .fragmentsAllowed]),
                  let str = String(data: out, encoding: .utf8) else { return s }
            return str
        }
    }
}

// MARK: - Paste service

final class PasteService {
    static let shared = PasteService()
    var pasteboard: NSPasteboard = .general

    /// The clip(s) Pastly last put on `pasteboard` (by double-click, ↩, ⌘V, Copy or a selection)
    /// and the changeCount that write produced. Kept separate from the history: it never reorders or
    /// re-times anything. Saved so it survives a relaunch.
    struct Choice: Codable, Equatable { var ids: [String]; var changeCount: Int }
    private static let choiceKey = "lastClipboardChoice"
    private(set) var lastChoice: Choice? = {
        guard let d = UserDefaults.standard.data(forKey: PasteService.choiceKey) else { return nil }
        return try? JSONDecoder().decode(Choice.self, from: d)
    }() {
        didSet { UserDefaults.standard.set(lastChoice.flatMap { try? JSONEncoder().encode($0) }, forKey: Self.choiceKey) }
    }

    /// IDs of the clips that ⌘V pastes right now — only while nothing newer has been copied since
    /// Pastly's own write. nil after any real copy in another app.
    var currentChoiceIDs: [String]? {
        guard let c = lastChoice, c.changeCount == pasteboard.changeCount else { return nil }
        return c.ids
    }

    /// Writes one item to the pasteboard. See `write(_ items:)`.
    @discardableResult
    func write(_ item: ClipItem, plainText: Bool = false, transform: TextTransform? = nil,
               images: ImageStore? = nil, to target: NSPasteboard? = nil) -> Int {
        write([item], plainText: plainText, transform: transform, images: images, to: target)
    }

    /// Writes items to the pasteboard. Records the expected changeCount BEFORE writing
    /// so ClipboardMonitor ignores this write. Returns the expected changeCount.
    ///
    /// Several text-like items (text, links, colors) are joined with newlines into one text clip.
    /// A mix with images/files becomes several pasteboard items (Finder, Mail, Notes accept these).
    @discardableResult
    func write(_ items: [ClipItem], plainText: Bool = false, transform: TextTransform? = nil,
               images: ImageStore? = nil, to target: NSPasteboard? = nil) -> Int {
        let pb = target ?? pasteboard
        let expected = pb.clearContents()                               // new changeCount for this write
        SelfWriteRegistry.shared.register(expected, pasteboard: pb.name) // registered before any data

        var pbItems: [NSPasteboardItem] = []
        if items.count > 1 && items.allSatisfy({ $0.type.isTextual }) {
            let it = NSPasteboardItem()
            var text = items.compactMap(\.pasteableText).joined(separator: "\n")
            if let t = transform { text = t.apply(text) }
            it.setString(text, forType: .string)
            pbItems.append(it)
        } else {
            var providers: [ImageFileProvider] = []
            for item in items {
                let store = images ?? ClipStore.shared.images
                let its = pasteboardItems(for: item, plainText: plainText, transform: transform, images: store)
                // Image clips also offer a real file (named like the clip), as dragging does, so ⌘V works in
                // Finder and other places that take files. It's written only when an app asks for it.
                if item.type == .image, item.imagePath != nil, let first = its.first {
                    let provider = ImageFileProvider(item: item, images: store)
                    first.setDataProvider(provider, forTypes: [.fileURL])
                    providers.append(provider)
                }
                pbItems += its
            }
            fileProviders[pb.name.rawValue] = providers   // kept alive while this content is on that pasteboard
        }
        if pbItems.isEmpty { pbItems.append(NSPasteboardItem()) }
        pbItems[0].setData(Data("1".utf8), forType: .pastlyInternal)
        pb.writeObjects(pbItems)

        // Defensive: if the write itself bumped the counter, register that value too.
        if pb.changeCount != expected {
            SelfWriteRegistry.shared.register(pb.changeCount, pasteboard: pb.name)
        }
        if pb === pasteboard { lastChoice = Choice(ids: items.map(\.id), changeCount: pb.changeCount) }
        return expected
    }

    private var fileProviders: [String: [ImageFileProvider]] = [:]

    /// Native pasteboard representations of a clip (used by paste and by dragging).
    func pasteboardItems(for item: ClipItem, plainText: Bool, transform: TextTransform?,
                                 images: ImageStore) -> [NSPasteboardItem] {
        switch item.type {
        case .file:
            let items = item.fileURLs.map { url -> NSPasteboardItem in
                let it = NSPasteboardItem()
                it.setString(url.absoluteString, forType: .fileURL)
                return it
            }
            // Image files also carry the image itself, for apps that take pictures rather than files.
            if let first = items.first, let name = item.imagePath { Self.addImage(name, images: images, to: first) }
            return items
        case .image:
            let it = NSPasteboardItem()
            if let name = item.imagePath { Self.addImage(name, images: images, to: it) }
            return [it]
        case .text, .url, .color:
            let it = NSPasteboardItem()
            var text = item.pasteableText ?? ""
            if let t = transform { text = t.apply(text) }
            it.setString(text, forType: .string)
            if !plainText && transform == nil {
                if let rtf = item.rtfData { it.setData(rtf, forType: .rtf) }
                if let html = item.htmlData { it.setData(html, forType: .html) }
                if item.type == .url { it.setString(text, forType: .URL) }
            }
            return [it]
        }
    }

    /// The stored image in its own format (JPEG, HEIC, PNG…) plus TIFF, which every Mac app reads.
    private static func addImage(_ name: String, images: ImageStore, to it: NSPasteboardItem) {
        guard let data = images.data(for: name) else { return }
        let uti = images.uti(for: name)
        it.setData(data, forType: NSPasteboard.PasteboardType(uti.identifier))
        if uti != .png, uti != .tiff, let tiff = NSImage(data: data)?.tiffRepresentation {
            it.setData(tiff, forType: .tiff)
        } else if uti == .png, let tiff = NSImage(data: data)?.tiffRepresentation {
            it.setData(tiff, forType: .tiff)
        }
    }

    /// Writes the item, then pastes it into `app` by sending ⌘V (needs Accessibility permission).
    /// Marks ⌘V events posted by Pastly so the paste queue's key watcher can ignore them.
    static let syntheticEventTag: Int64 = 0x5053_5448

    func paste(_ items: [ClipItem], plainText: Bool, transform: TextTransform?, into app: NSRunningApplication?,
               completion: ((Bool) -> Void)? = nil) {
        guard !items.isEmpty else { completion?(false); return }
        write(items, plainText: plainText, transform: transform)
        // Counts the paste; the history order and timestamps stay as they are.
        for item in items { ClipStore.shared.markUsed(item.id, pasted: true) }

        guard Preferences.shared.autoPaste else {
            NSApp.hide(nil)
            Toast.show("Copied — press ⌘V to paste")
            completion?(false)
            return
        }
        guard AXIsProcessTrusted() else {
            NSLog("Pastly: auto-paste skipped, Accessibility not granted")
            Onboarding.accessibilityMissingAfterCopy()
            completion?(false)
            return
        }

        // Hand focus back to the target app *before* hiding, while we are still the active app
        // (macOS 14+ cooperative activation only honors requests from the active app).
        if let app, !app.isTerminated {
            app.activate(from: .current, options: [])
        }
        NSApp.hide(nil)

        let targetPID = app?.processIdentifier
        waitUntilReady(targetPID: targetPID, deadline: Date().addingTimeInterval(1.0)) { ready in
            let front = NSWorkspace.shared.frontmostApplication
            if front?.processIdentifier == ProcessInfo.processInfo.processIdentifier {
                // Still frontmost: ⌘V would land in Pastly itself.
                NSLog("Pastly: target app did not come to front; copied only")
                Toast.show("Copied — press ⌘V to paste")
                completion?(false)
                return
            }
            if IsSecureEventInputEnabled() {
                NSLog("Pastly: secure input is on in %@; copied only", front?.localizedName ?? "?")
                Toast.show("Copied — secure input is on here, press ⌘V to paste")
                completion?(false)
                return
            }
            if !ready { NSLog("Pastly: target not confirmed frontmost, pasting into %@", front?.localizedName ?? "?") }
            Self.sendCommandV()
            completion?(true)
        }
    }

    /// Polls until the target app is frontmost and the user has released modifier keys
    /// (e.g. ⌥ from ⌥↩ or ⌘ from ⌘1), so the target sees a clean ⌘V.
    private func waitUntilReady(targetPID: pid_t?, deadline: Date, then action: @escaping (Bool) -> Void) {
        let frontOK: Bool = {
            guard let front = NSWorkspace.shared.frontmostApplication else { return false }
            if let pid = targetPID { return front.processIdentifier == pid }
            return front.processIdentifier != ProcessInfo.processInfo.processIdentifier
        }()
        let held = CGEventSource.flagsState(.combinedSessionState)
            .intersection([.maskCommand, .maskAlternate, .maskShift, .maskControl])
        let modifiersReleased = held.isEmpty
        if frontOK && modifiersReleased {
            // Small settle delay so the app's key window is ready to receive events.
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) { action(true) }
        } else if Date() >= deadline {
            action(frontOK)
        } else {
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.02) {
                self.waitUntilReady(targetPID: targetPID, deadline: deadline, then: action)
            }
        }
    }

    /// Posts a full ⌘ down → V down → V up → ⌘ up sequence at the HID level, which works in
    /// apps that ignore session-level or flag-only events (Chrome, Electron, Java, terminals).
    static func sendCommandV() {
        let src = CGEventSource(stateID: .combinedSessionState)
        src?.setLocalEventsFilterDuringSuppressionState(
            [.permitLocalMouseEvents, .permitSystemDefinedEvents],
            state: .eventSuppressionStateSuppressionInterval)
        let cmdKey: CGKeyCode = 0x37
        let vKey = KeyboardLayout.keyCode(for: "v") ?? 0x09

        let cmdDown = CGEvent(keyboardEventSource: src, virtualKey: cmdKey, keyDown: true)
        cmdDown?.flags = .maskCommand
        let vDown = CGEvent(keyboardEventSource: src, virtualKey: vKey, keyDown: true)
        vDown?.flags = .maskCommand
        let vUp = CGEvent(keyboardEventSource: src, virtualKey: vKey, keyDown: false)
        vUp?.flags = .maskCommand
        let cmdUp = CGEvent(keyboardEventSource: src, virtualKey: cmdKey, keyDown: false)
        cmdUp?.flags = []

        for event in [cmdDown, vDown, vUp, cmdUp] {
            event?.setIntegerValueField(.eventSourceUserData, value: syntheticEventTag)
            event?.post(tap: .cghidEventTap)
        }
    }
}

/// Finds the physical key that types a character on the user's current (ASCII-capable) layout,
/// so ⌘V works on Dvorak, AZERTY, Colemak, etc. — not just QWERTY.
enum KeyboardLayout {
    private static var cache: [String: CGKeyCode] = [:]
    private static var cachedLayoutID: String?

    static func keyCode(for character: String) -> CGKeyCode? {
        guard let source = TISCopyCurrentASCIICapableKeyboardLayoutInputSource()?.takeRetainedValue(),
              let layoutPtr = TISGetInputSourceProperty(source, kTISPropertyUnicodeKeyLayoutData) else { return nil }

        let layoutID = TISGetInputSourceProperty(source, kTISPropertyInputSourceID)
            .map { Unmanaged<CFString>.fromOpaque($0).takeUnretainedValue() as String }
        if layoutID != cachedLayoutID { cache = [:]; cachedLayoutID = layoutID }
        if let hit = cache[character] { return hit }

        let layoutData = Unmanaged<CFData>.fromOpaque(layoutPtr).takeUnretainedValue() as Data
        let found: CGKeyCode? = layoutData.withUnsafeBytes { raw -> CGKeyCode? in
            guard let layout = raw.baseAddress?.assumingMemoryBound(to: UCKeyboardLayout.self) else { return nil }
            for code in 0..<128 {
                var deadKeys: UInt32 = 0
                var length = 0
                var chars = [UniChar](repeating: 0, count: 4)
                let status = UCKeyTranslate(layout, UInt16(code), UInt16(kUCKeyActionDisplay), 0,
                                            UInt32(LMGetKbdType()), OptionBits(kUCKeyTranslateNoDeadKeysBit),
                                            &deadKeys, chars.count, &length, &chars)
                if status == noErr, length > 0,
                   String(utf16CodeUnits: chars, count: length).lowercased() == character {
                    return CGKeyCode(code)
                }
            }
            return nil
        }
        if let found { cache[character] = found }
        return found
    }
}

/// Small non-activating message bubble ("Copied — press ⌘V"). Never steals focus.
enum Toast {
    private static var window: NSPanel?
    private static var hideWork: DispatchWorkItem?

    static func show(_ message: String, duration: TimeInterval = 1.8) {
        let label = NSTextField(labelWithString: message)
        label.font = .systemFont(ofSize: 13, weight: .medium)
        label.textColor = .labelColor
        label.sizeToFit()
        let size = NSSize(width: label.frame.width + 32, height: 36)

        let panel = window ?? {
            let p = NSPanel(contentRect: .zero, styleMask: [.borderless, .nonactivatingPanel],
                            backing: .buffered, defer: false)
            p.level = .statusBar
            p.isOpaque = false
            p.backgroundColor = .clear
            p.hasShadow = true
            p.ignoresMouseEvents = true
            p.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .transient]
            window = p
            return p
        }()

        let effect = NSVisualEffectView(frame: NSRect(origin: .zero, size: size))
        effect.material = .hudWindow
        effect.state = .active
        effect.wantsLayer = true
        effect.layer?.cornerRadius = 10
        effect.layer?.masksToBounds = true
        label.frame.origin = NSPoint(x: 16, y: (size.height - label.frame.height) / 2)
        effect.addSubview(label)
        panel.contentView = effect

        let mouse = NSEvent.mouseLocation
        let screen = NSScreen.screens.first { NSMouseInRect(mouse, $0.frame, false) } ?? NSScreen.main
        if let vf = screen?.visibleFrame {
            panel.setFrame(NSRect(x: vf.midX - size.width / 2, y: vf.maxY - size.height - 24,
                                  width: size.width, height: size.height), display: true)
        }
        panel.alphaValue = 1
        panel.orderFrontRegardless()

        hideWork?.cancel()
        let work = DispatchWorkItem { panel.orderOut(nil) }
        hideWork = work
        DispatchQueue.main.asyncAfter(deadline: .now() + duration, execute: work)
    }
}


/// Supplies the image file of an image clip on demand (when an app such as Finder asks for a file on ⌘V).
/// The file is the same one dragging uses (`DragFiles`), named after the clip, e.g. "Screenshot … PM.png".
final class ImageFileProvider: NSObject, NSPasteboardItemDataProvider {
    private let item: ClipItem
    private let images: ImageStore

    init(item: ClipItem, images: ImageStore) {
        self.item = item
        self.images = images
    }

    func pasteboard(_ pasteboard: NSPasteboard?, item pbItem: NSPasteboardItem, provideDataForType type: NSPasteboard.PasteboardType) {
        guard type == .fileURL, let name = item.imagePath, let data = images.data(for: name),
              let url = DragFiles.file(for: item, data: data, ext: (name as NSString).pathExtension) else { return }
        pbItem.setString(url.absoluteString, forType: .fileURL)
    }
}
